def branch_execute(self, sim, caster, target, context=None, ability=None, proc_chance=None) -> tuple[bool, bool]:
    """Evaluates branch conditions and sequentially executes its actions.

    ``proc_chance`` (0-100) is rolled only after the conditions pass, so a branch whose
    conditions fail never draws from the RNG.

    Returns ``(branch_ran, branch_succeeded)``.
    """
    actual_target = _resolve_target_overrides(self.target_overrides, target, caster, context)

    if self.conditions:
        if not validate_all(self.conditions, caster, actual_target, sim=sim, context=context):
            return False, True

    if proc_chance is not None and proc_chance < 100.0:
        draw = random.random() * 100.0
        triggers = getattr(sim, "triggers", None)
        pending = getattr(triggers, "lifecycle_pending", None)
        forced_draws = getattr(triggers, "forced_draws", None)
        if pending is not None and forced_draws:
            key = (pending["fqn"], pending["effect_key"], pending["branch_index"], pending["trigger_index"])
            forced = forced_draws.get(key)
            if forced is not None:
                draw = forced
        if pending is not None:
            pending["draw"] = draw
            pending["outcome"] = "roll_failed" if draw > proc_chance else "roll_passed"
        if draw > proc_chance:
            return False, True

    source_name = ability.name if ability else "Unknown"
    combat_outcomes: list[bool] = []
    crit_flags: list = []  # True / False / None (unknown), parallel to combat_outcomes

    # A branch whose damage action is followed by more actions (main + off-hand hits, or a hit followed by
    # call_effect etc.) resolves from one state: post-hit triggers (buff consumption, procs) wait until the
    # whole branch has run. A branch whose only damage action is its last action dispatches immediately.
    group = None
    previous_group = None
    if sim is not None:
        previous_group = getattr(sim, "hit_group", None)
        if any(a.get("action_type") == "damage" for a in self.actions[:-1]):
            group = HitGroup()
        if group is not None or previous_group is not None:
            sim.hit_group = group
    try:
        for action in self.actions:
            action_type = action.get("action_type")

            req = set(action.get("results") or ())
            if (action.get("combat_math_only", False) or req) and combat_outcomes:
                agg = all if action.get("match_all", False) else any
                hit = agg(combat_outcomes)
                if req and req <= FAIL_RESULTS:
                    passed = not hit  # only when the attack failed
                elif req == {"effResultCrit"}:
                    vals = [(f if f is not None else o)  # unknown crit: fall back to "hit"
                            for f, o in zip(crit_flags, combat_outcomes)]
                    passed = agg(vals)
                else:
                    passed = hit  # any-hit gate
                if not passed:
                    continue

            action_source = source_name
            if action_type == "damage":
                action_source = damage_source_name(context, source_name)

            success = execute_single_action(
                sim, caster, actual_target, action, action_source, ability=ability, context=context
            )

            if action_type == "damage":
                combat_outcomes.append(bool(success))
                crit_flags.append(getattr(success, "crit", None) if success else False)
            elif not success:
                return True, False
    finally:
        if group is not None or previous_group is not None:
            sim.hit_group = previous_group
        if group is not None:
            group.seal(sim)

    branch_success = any(combat_outcomes) if combat_outcomes else True
    return True, branch_success


def effect_execute_triggered_branches(
    self,
    trigger_name: str,
    sim,
    caster,
    target,
    context=None,
    ability=None,
    include_untriggered: bool = False,
    tick_number: Optional[int] = None,
):
    """Executes branches matching trigger_name (and optionally untriggered branches)."""
    branch_context = dict(context) if context else {}
    existing_tags = set(branch_context.get("effect_tags") or ())
    branch_context["effect_tags"] = existing_tags | set(self.tags or ())
    branch_context["effect"] = self
    executed_branches = set()
    for branch in self.branches:
        triggers = getattr(branch, "triggers", [])
        proc_chance = None
        base_proc_chance = None
        matched_index = None
        if not triggers:
            if not include_untriggered:
                continue
        else:
            matched = False
            for t_index, t in enumerate(triggers):
                if t.get("trigger") != trigger_name:
                    continue
                if trigger_name == "on_tick" and tick_number is not None:
                    t_num = t.get("tick_number") or 0
                    if t_num not in (0, tick_number):
                        continue
                if trigger_name in ("on_stack_charge_increased", "on_stack_charge_decreased"):
                    ints = t.get("ints") or {}
                    req_count = ints.get("count") if "count" in ints else t.get("count")
                    if req_count is not None and int(req_count) > 0:
                        # The owner effect's live stacks: on the modify_stack_charge path the context's
                        # current_stacks is copied from the calling branch.
                        current_stacks = owner_effect_stacks(branch_context)
                        if current_stacks is None:
                            current_stacks = branch_context.get("current_stacks")
                        if current_stacks is not None and int(current_stacks) < int(req_count):
                            continue
                if trigger_name == "on_channeling_ended":
                    bools = t.get("bools") or {}
                    if "is_successful" in bools and "is_successful" in branch_context:
                        if bools["is_successful"] != branch_context["is_successful"]:
                            continue
                if trigger_name in _LIFECYCLE_TRIGGERS:
                    # The TriggerManager never dispatches lifecycle triggers, so their proc chance is
                    # honored here (Deathmark's 50% stack refund, Forked Darkness' 25% per DoT tick).
                    proc_chance = (t.get("floats") or {}).get("proc_chance_percent")
                    base_proc_chance = proc_chance
                    if proc_chance is not None:
                        # Stat 228 bonuses, matched as on the bus: trigger tags + the owning effect's tags.
                        _, proc_chance_mods = _collect_trigger_mods(caster)
                        proc_chance = effective_proc_chance(
                            proc_chance,
                            proc_chance_mods,
                            getattr(ability, "fqn", None),
                            set(t.get("tags") or ()) | set(self.tags or ()),
                        )
                matched = True
                matched_index = t_index
                break
            if not matched:
                continue

        lifecycle_log = getattr(getattr(sim, "triggers", None), "proc_log", None)
        record = None
        if lifecycle_log is not None and matched_index is not None and trigger_name in _LIFECYCLE_TRIGGERS:
            record = {
                "t": sim.current_time, "event": trigger_name, "outcome": "pending",
                "source": getattr(ability, "name", None) or getattr(ability, "fqn", None),
                "fqn": getattr(ability, "fqn", None), "effect_key": self.name,
                "branch_index": branch.index, "trigger_index": matched_index, "kind": "lifecycle",
                "base_chance": base_proc_chance, "chance": proc_chance, "draw": None, "node": None,
                "cause": (sim.tracer.current_cause_id() if getattr(sim, "tracer", None) is not None else None),
            }
            lifecycle_log.append(record)

        if branch.run_if_none_ran and any(b in executed_branches for b in branch.run_if_none_ran):
            if record is not None:
                record["outcome"] = "skipped_else_gate"
            continue

        if record is not None:
            sim.triggers.lifecycle_pending = record
        ran, success = branch.execute(
            sim, caster, target, context=branch_context, ability=ability, proc_chance=proc_chance
        )
        if record is not None:
            sim.triggers.lifecycle_pending = None
            if record["outcome"] in ("pending", "roll_passed"):
                record["outcome"] = "fired" if ran else "blocked_condition"
        if ran:
            executed_branches.add(branch.index)
